"""Project-type detection and the per-type toolchain profile. Pure functions, no container work.

Types: foundry, rust, desktop, monorepo, web_app, node_lib, unsupported.
`files` maps a manifest name to its text in the project directory; `members` maps the path of a
workspace member's package.json to its text.
"""
import json
import re

WEB_DEPS = {"next", "nuxt", "vite", "express", "fastify", "koa", "hono", "@nestjs/core",
            "react-scripts", "@remix-run/dev", "@remix-run/node", "astro", "@sveltejs/kit",
            "gatsby", "@hapi/hapi", "@angular/cli"}
CAP_MINUTES = {"node": 15, "foundry": 10, "rust": 25}   # time cap per toolchain family
FOUNDRY_RELEASE = "v1.8.5"
MANIFESTS = ["package.json", "pnpm-workspace.yaml", "foundry.toml", "Cargo.toml",
             "rust-toolchain", "rust-toolchain.toml", ".env.example"]
SECRETISH = re.compile(r"KEY|SECRET|TOKEN|PASSWORD|PASSWD|URL|URI|DSN|DATABASE|CLIENT_ID|MNEMONIC|"
                       r"PRIVATE|RPC|WEBHOOK", re.I)


def _pkg(text):
    try:
        pkg = json.loads(text or "{}")
    except ValueError:
        return {}
    return pkg if isinstance(pkg, dict) else {}


def _deps(pkg):
    return {**(pkg.get("devDependencies") or {}), **(pkg.get("dependencies") or {})}


def scripts(files):
    s = _pkg(files.get("package.json")).get("scripts")
    return s if isinstance(s, dict) else {}


def has_real_test(files):
    test = scripts(files).get("test")
    return isinstance(test, str) and "no test specified" not in test


def detect_type(files, members=None):
    """(type, why)."""
    if "foundry.toml" in files:
        return "foundry", "foundry.toml present"
    if "Cargo.toml" in files:
        ws = "workspace" if re.search(r"^\[workspace\]", files["Cargo.toml"], re.M) else "package"
        return "rust", f"Cargo.toml present ({ws})"
    if "package.json" not in files:
        return "unsupported", "no package.json, foundry.toml or Cargo.toml"
    pkg = _pkg(files["package.json"])
    if "electron" in _deps(pkg):
        return "desktop", "electron dependency in package.json"
    for path, text in (members or {}).items():
        if "electron" in _deps(_pkg(text)):
            return "desktop", f"electron dependency in {path}"
    if "pnpm-workspace.yaml" in files:
        return "monorepo", "pnpm-workspace.yaml present"
    if pkg.get("workspaces"):
        return "monorepo", "package.json has a workspaces field"
    s = scripts(files)
    for name in ("start", "dev"):
        if name in s:
            return "web_app", f"package.json has a {name} script"
    web = sorted(WEB_DEPS & _deps(pkg).keys())
    if web:
        return "web_app", f"web framework dependency {web[0]}"
    return "node_lib", "package.json without start/dev script or web framework"


def family(ptype):
    return ptype if ptype in ("foundry", "rust") else "node"


def rust_version(files):
    """Image version tag: the pinned toolchain if rust-toolchain(.toml) names a release, else
    the latest stable (`1`). Returns (tag, why)."""
    text = files.get("rust-toolchain.toml") or files.get("rust-toolchain") or ""
    m = re.search(r'channel\s*=\s*"([^"]+)"', text) or re.match(r"\s*([^\s#\[]+)", text)
    channel = m.group(1) if m else ""
    if re.fullmatch(r"\d+\.\d+(\.\d+)?", channel):
        return channel, f"rust-toolchain pins {channel}"
    return "1", f"stable ({channel or 'no rust-toolchain file'})"


def _dummy(name):
    n = name.upper()
    if re.search(r"DATABASE|POSTGRES|PG_|DB_URL", n) and "URL" in n:
        return "REDACTED"
    if "REDIS" in n and "URL" in n:
        return "redis://localhost:6379"
    if re.search(r"PRIVATE_KEY|(^|_)PK$|MNEMONIC", n):
        return "0x" + "11" * 32
    if "ADDRESS" in n:
        return "0x" + "00" * 20
    if re.search(r"URL|URI|ENDPOINT|RPC|HOST", n):
        return "http://localhost:3000"
    if n.endswith("PORT"):
        return "3000"
    if re.search(r"KEY|SECRET|TOKEN|PASSWORD|PASSWD|DSN", n):
        return "dummy-secret-value"
    if "DOMAIN" in n:
        return "localhost"
    return "dummy"


def env_names(example):
    return re.findall(r"^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=", example, re.M)


def dummy_env(example):
    """Contents of a .env made from .env.example: concrete example values are kept,
    empty or placeholder ones get a safe dummy chosen from the variable name."""
    out = []
    for line in example.splitlines():
        m = re.match(r"\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)", line)
        if not m:
            continue
        name, value = m.group(1), re.sub(r"\s+#.*$", "", m.group(2)).strip().strip("\"'")
        if not value or re.search(r"^your|^<|xxx|change.?me|replace|\.\.\.|^todo", value, re.I):
            value = _dummy(name)
        out.append(f"{name}={value}")
    return "\n".join(out) + "\n"


def needs_secret(output, example):
    """First secret-like variable from .env.example that the failing output names, or None."""
    for name in env_names(example):
        if SECRETISH.search(name) and re.search(rf"\b{re.escape(name)}\b", output):
            return name
    return None
"""LangGraph repair loop: run -> (rules) -> diagnose -> propose -> apply -> run ...

Only the model-facing and decision logic lives here; container work is done by `box`
(see run.Box). The neatlogs handler is attached by the caller at graph invoke, so the nodes
below create no spans of their own.
"""
import json
import re
import time
from typing import TypedDict

from langchain_core.messages import AIMessage, HumanMessage, SystemMessage
from langchain_core.runnables import RunnableConfig
from langgraph.graph import END, START, StateGraph

from resurgo.gateway import MAX_REQUEST_BYTES, ModelLimited, ModelUnavailable
from resurgo.rules import LOCKFILES, apply_rules

MAX_ATTEMPTS = 4          # fix attempts per repo, a rule candidate counts as one
CONFIG_NAMES = {".nvmrc", ".node-version", ".npmrc", ".yarnrc", ".yarnrc.yml",
                "pnpm-workspace.yaml", ".tool-versions", "foundry.toml", "rust-toolchain",
                "rust-toolchain.toml", ".env.example"}
PACKAGE_JSON_KEYS = {"packageManager", "engines", "volta", "pnpm", "overrides", "resolutions",
                     "devEngines"}
LOCKFILE_NAMES = {n for n, _ in LOCKFILES} | {"Cargo.lock"}
UNFIXABLE_STEPS = {"toolchain"}
MANIFEST_BYTES = 12_000

SYSTEM = """You repair a project (Node.js, Foundry or Rust) that fails on a fresh machine. \
Diagnose the failing step (install, build, test, or serve: start the server and GET /) from \
the command, exit code and output, then reply with ONE JSON object and nothing else:
{"kind": "config" | "code", "files": [{"path": "<path relative to the repo root>", \
"content": "<complete new file content>"}], "rationale": "<why this fixes it>", \
"confidence": <number from 0 to 1>}
kind "config": only version pins and tool settings: .nvmrc, .node-version, .npmrc, .yarnrc, \
.yarnrc.yml, pnpm-workspace.yaml, foundry.toml, rust-toolchain(.toml), .env.example, and in \
package.json only the packageManager, engines, volta, \
pnpm (for example onlyBuiltDependencies), overrides, resolutions and devEngines fields. Give \
complete file contents; keep every other package.json field unchanged. To regenerate a lockfile, \
list it (or Cargo.lock) with content "". These are applied and re-run.
kind "code": any change to source, scripts or dependencies. These are NOT applied; they are \
recorded for human approval. Prefer a config fix when one exists."""


class State(TypedDict, total=False):
    failure: dict
    attempts: list
    rules_tried: bool
    rule_applied: bool
    rules_fired: list
    system: str
    user: str
    raw: str
    proposal: dict
    reasked: bool
    status: str
    detail: str


def parse_proposal(raw):
    """(proposal, error). Strict JSON; a leading ```json fence is tolerated."""
    text = raw.strip()
    m = re.match(r"^```(?:json)?\s*(.*?)\s*```$", text, re.S)
    if m:
        text = m.group(1)
    try:
        p = json.loads(text)
    except ValueError as e:
        return None, f"not valid JSON: {e}"
    if not isinstance(p, dict):
        return None, "top level must be a JSON object"
    if p.get("kind") not in ("config", "code"):
        return None, 'kind must be "config" or "code"'
    files = p.get("files")
    if not isinstance(files, list):
        return None, "files must be a list"
    for f in files:
        if not (isinstance(f, dict) and isinstance(f.get("path"), str) and isinstance(f.get("content"), str)):
            return None, 'each file needs a string "path" and a string "content"'
        parts = f["path"].split("/")
        if f["path"].startswith("/") or ".." in parts or parts[0] == ".git" or not f["path"]:
            return None, f"unsafe path {f['path']!r}"
    if not isinstance(p.get("rationale"), str):
        return None, "rationale must be a string"
    c = p.get("confidence")
    if isinstance(c, bool) or not isinstance(c, (int, float)) or not 0 <= c <= 1:
        return None, "confidence must be a number between 0 and 1"
    return p, None


def config_problem(box, proposal):
    """Why this config proposal cannot be applied automatically, or None."""
    for f in proposal["files"]:
        name = f["path"].rsplit("/", 1)[-1]
        if name in LOCKFILE_NAMES:
            if f["content"] != "":
                return f"{f['path']}: a lockfile can only be regenerated (content \"\")"
        elif name == "package.json":
            old = box.read(f["path"])
            try:
                old, new = json.loads(old or "{}"), json.loads(f["content"])
            except ValueError:
                return f"{f['path']}: not valid JSON"
            changed = {k for k in old.keys() | new.keys() if old.get(k) != new.get(k)}
            if changed - PACKAGE_JSON_KEYS:
                return f"{f['path']}: changes {sorted(changed - PACKAGE_JSON_KEYS)}, which is not config"
        elif name not in CONFIG_NAMES:
            return f"{f['path']}: not a config file"
    return None


def build_prompt(box, failure, attempts):
    """User message: command, exit code, manifests, history, then as much output tail as fits
    under the request limit."""
    parts = [f"Project type: {box.ptype} ({box.why}); image {box.image}",
             f"Failing step: {failure['step']}", f"Command: {failure['command']}",
             f"Exit code: {failure['exit_code']}", f"Environment: {box.versions or 'unknown'}",
             f"Project path in repo: {box.subdir or '.'}"]
    if attempts:
        parts.append("Previous attempts (do not repeat what failed):")
        for a in attempts:
            parts.append(f"- {a['source']} {a['kind']} {a['files']}: {a.get('result')}")
    names = ["package.json", ".nvmrc", ".node-version", ".npmrc", ".yarnrc.yml",
             "pnpm-workspace.yaml", "foundry.toml", "Cargo.toml", "rust-toolchain.toml",
             "rust-toolchain", ".env.example"] + sorted(LOCKFILE_NAMES)
    found = box.read_many([p for n in names for p in {box.rel(n), n}])
    seen = set()
    for name in names:
        for path in (box.rel(name), name):
            if path in seen:
                continue
            seen.add(path)
            text = found.get(path)
            if text is None:
                continue
            if name in LOCKFILE_NAMES:
                text = "\n".join(text.splitlines()[:30]) + "\n[lockfile truncated]"
            parts.append(f"--- {path} ---\n{text[:MANIFEST_BYTES]}")
    head = "\n\n".join(parts) + "\n\n--- output tail ---\n"
    # leave room for a re-ask (the reply plus an error line) inside the same limit
    room = MAX_REQUEST_BYTES - len((SYSTEM + head).encode()) - 8_000
    tail = box.last_out.encode()[-max(room, 0):].decode(errors="ignore")
    return head + tail


def build_graph(box, model, deadline):
    def over_budget():
        return time.monotonic() > deadline

    def applied(state):
        return [a for a in state.get("attempts", []) if a["status"] == "applied"]

    def settle(attempts, result):
        """Record how the last applied attempt turned out once it has been re-run."""
        if attempts and attempts[-1]["status"] == "applied" and attempts[-1].get("result") is None:
            attempts = attempts[:-1] + [{**attempts[-1], "result": result}]
        return attempts

    def run(state):
        if over_budget():
            return {"status": "budget_exhausted", "detail": f"{box.cap_s // 60} minute budget used"}
        failure = box.pipeline()
        attempts = settle(state.get("attempts", []),
                          "passed" if failure is None else f"failed at {failure['step']}")
        if failure is None:
            return {"status": "passed", "failure": {}, "attempts": attempts}
        out = {"failure": failure, "attempts": attempts}
        if failure["step"] in UNFIXABLE_STEPS:
            out.update(status="fail", detail=f"{failure['step']} failed; not a fixable step")
        elif len(applied({"attempts": attempts})) >= MAX_ATTEMPTS:
            out.update(status="budget_exhausted", detail=f"{MAX_ATTEMPTS} fix attempts used")
        return out

    def rules(state):
        fired, fixes = apply_rules(box.rule_files())
        attempts = list(state.get("attempts", []))
        if fixes:
            paths = box.write({box.rel(n): c for n, c in fixes.items()})
            attempts.append({"source": "rule", "kind": "config", "files": paths,
                             "rationale": "; ".join(f"{r['rule']}: {r['value']} from {r['source']}"
                                                    for r in fired),
                             "confidence": None, "status": "applied", "result": None})
        return {"rules_tried": True, "rule_applied": bool(fixes), "rules_fired": fired,
                "attempts": attempts}

    def ask(messages, config):
        return model.invoke(messages, config).content

    def failed_model(e):
        if isinstance(e, ModelLimited):
            return {"status": "model_limited", "detail": str(e)}
        return {"status": "model_unavailable", "detail": str(e)}

    def diagnose(state, config: RunnableConfig):
        if over_budget():
            return {"status": "budget_exhausted", "detail": f"{box.cap_s // 60} minute budget used"}
        user = build_prompt(box, state["failure"], state.get("attempts", []))
        try:
            raw = ask([SystemMessage(SYSTEM), HumanMessage(user)], config)
        except (ModelLimited, ModelUnavailable) as e:
            return failed_model(e)
        return {"system": SYSTEM, "user": user, "raw": raw, "reasked": False}

    def propose(state, config: RunnableConfig):
        proposal, err = parse_proposal(state["raw"])
        if err:
            msgs = [SystemMessage(state["system"]), HumanMessage(state["user"]),
                    AIMessage(state["raw"][:4000]),
                    HumanMessage(f"That reply was rejected: {err}. "
                                 "Reply again with only the JSON object.")]
            try:
                raw = ask(msgs, config)
            except (ModelLimited, ModelUnavailable) as e:
                return failed_model(e)
            proposal, err = parse_proposal(raw)
            if err:
                return {"status": "invalid_proposal", "detail": err, "raw": raw}
            return {"proposal": {**proposal, "recovered_from_invalid_json": True}, "raw": raw}
        return {"proposal": proposal}

    def apply(state):
        p = state["proposal"]
        attempts = list(state.get("attempts", []))
        entry = {"source": "model", "kind": p["kind"], "files": [f["path"] for f in p["files"]],
                 "rationale": p["rationale"], "confidence": p["confidence"], "result": None,
                 "recovered_from_invalid_json": p.get("recovered_from_invalid_json", False)}
        problem = None
        if p["kind"] == "code":
            problem = "code fix, not applied in this milestone"
        elif not p["files"]:
            problem = "config proposal has no files"
        else:
            problem = config_problem(box, p)
        if problem:
            entry.update(status="needs_approval", result=problem, files_content=p["files"])
            status = "needs_approval" if p["files"] else "fail"
            return {"attempts": attempts + [entry], "status": status, "detail": problem}
        box.write({f["path"]: f["content"] for f in p["files"] if f["content"] != ""})
        box.remove([f["path"] for f in p["files"] if f["content"] == ""])
        entry["status"] = "applied"
        return {"attempts": attempts + [entry]}

    def after_run(state):
        if state.get("status"):
            return END
        return "diagnose" if state.get("rules_tried") else "rules"

    g = StateGraph(State)
    for name, fn in [("run", run), ("rules", rules), ("diagnose", diagnose),
                     ("propose", propose), ("apply", apply)]:
        g.add_node(name, fn)
    g.add_edge(START, "run")
    g.add_conditional_edges("run", after_run, ["rules", "diagnose", END])
    g.add_conditional_edges("rules", lambda s: "run" if s["rule_applied"] else "diagnose",
                            ["run", "diagnose"])
    g.add_conditional_edges("diagnose", lambda s: END if s.get("status") else "propose",
                            ["propose", END])
    g.add_conditional_edges("propose", lambda s: END if s.get("status") else "apply",
                            ["apply", END])
    g.add_conditional_edges("apply", lambda s: END if s.get("status") else "run", ["run", END])
    return g.compile()
__version__ = "0.1.0"
// Wait for the server to open a new TCP port, GET / on it and check the response.
// Usage: node probe.js <server pid> <server log> <wait seconds>
const fs = require("fs");
const http = require("http");

const [pid, log, waitS] = process.argv.slice(2);
const BAD = ["Internal Server Error", "Application error", "Unhandled Runtime Error",
  "Failed to compile", "Module not found", "Cannot find module", "Cannot GET /",
  "__next_error__", "vite-error-overlay"];

const listening = () => {
  const ports = new Set();
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) {
    try {
      for (const l of fs.readFileSync(f, "utf8").split("\n").slice(1)) {
        const c = l.trim().split(/\s+/);
        if (c[3] === "0A") ports.add(parseInt(c[1].split(":")[1], 16));
      }
    } catch {}
  }
  return ports;
};
const tail = () => {
  try { return fs.readFileSync(log, "utf8").split("\n").slice(-40).join("\n"); } catch { return ""; }
};
const fail = (msg) => {
  console.log(`serve check failed: ${msg}\n--- server log tail ---\n${tail()}`);
  process.exit(1);
};
const alive = () => { try { process.kill(Number(pid), 0); return true; } catch { return false; } };
const get = (port) => new Promise((resolve) => {
  const req = http.get({ host: "localhost", port, path: "/", timeout: 60000 }, (r) => {
    let body = "";
    r.setEncoding("utf8");
    r.on("data", (d) => { if (body.length < 500000) body += d; });
    r.on("end", () => resolve({ status: r.statusCode, body }));
  });
  req.on("error", (e) => resolve({ error: e.message }));
  req.on("timeout", () => req.destroy(new Error("request timed out")));
});

(async () => {
  const before = listening();
  const end = Date.now() + Number(waitS) * 1000;
  let last = "no new port opened";
  while (Date.now() < end) {
    for (const port of [...listening()].filter((p) => !before.has(p))) {
      const r = await get(port);
      if (r.error) { last = `GET / on port ${port}: ${r.error}`; continue; }
      if (r.status < 200 || r.status >= 400) fail(`GET / returned HTTP ${r.status}`);
      if (!r.body.trim()) fail(`GET / returned an empty body (HTTP ${r.status})`);
      const bad = BAD.find((m) => r.body.includes(m));
      if (bad) fail(`GET / body contains the error marker "${bad}"`);
      console.log(`serve ok: GET / -> HTTP ${r.status}, ${r.body.length} bytes on port ${port}`);
      process.exit(0);
    }
    if (!alive()) fail("server exited before serving");
    await new Promise((r) => setTimeout(r, 1000));
  }
  fail(`${last} within ${waitS}s`);
})();
import json

from resurgo.project import detect_type, dummy_env, needs_secret
from resurgo.run import detect_pm


def test_detect_pm():
    assert detect_pm(["package.json", "pnpm-lock.yaml"]) == "pnpm"
    assert detect_pm(["yarn.lock"]) == "yarn"
    assert detect_pm(["package-lock.json"]) == "npm"
    assert detect_pm(["package.json"]) is None


def pkg(**kw):
    return {"package.json": json.dumps(kw)}


def test_detect_type():
    assert detect_type({"foundry.toml": "", **pkg(name="x")})[0] == "foundry"
    assert detect_type({"Cargo.toml": "[workspace]\n"})[0] == "rust"
    assert detect_type(pkg(devDependencies={"electron": "1"}))[0] == "desktop"
    member = {"apps/a/package.json": '{"dependencies": {"electron": "1"}}'}
    assert detect_type(pkg(name="m"), member)[0] == "desktop"
    assert detect_type({**pkg(name="m"), "pnpm-workspace.yaml": ""})[0] == "monorepo"
    assert detect_type(pkg(workspaces=["a"]))[0] == "monorepo"
    assert detect_type(pkg(scripts={"dev": "vite"}))[0] == "web_app"
    assert detect_type(pkg(dependencies={"express": "4"}))[0] == "web_app"
    assert detect_type(pkg(name="lib", scripts={"build": "tsc"}))[0] == "node_lib"
    assert detect_type({})[0] == "unsupported"
    env = dummy_env("API_KEY=\nSITE_URL=your-url\nPORT=8080 # port\n")
    assert env == "API_KEY=dummy-secret-value\nSITE_URL=http://localhost:3000\nPORT=8080\n"
    assert needs_secret("Error: API_KEY is not set", "API_KEY=\nPORT=1\n") == "API_KEY"


if __name__ == "__main__":
    test_detect_pm()
    test_detect_type()
    print("ok")
