// Wait for the server to open a new TCP port, GET / on it and check the response.
// Usage: node probe.js <server pid> <server log> <wait seconds>
const fs = require("fs");
const http = require("http");

const [pid, log, waitS] = process.argv.slice(2);
const BAD = ["Internal Server Error", "Application error", "Unhandled Runtime Error",
  "Failed to compile", "Module not found", "Cannot find module", "Cannot GET /",
  "__next_error__", "vite-error-overlay"];

const listening = () => {
  const ports = new Set();
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) {
    try {
      for (const l of fs.readFileSync(f, "utf8").split("\n").slice(1)) {
        const c = l.trim().split(/\s+/);
        if (c[3] === "0A") ports.add(parseInt(c[1].split(":")[1], 16));
      }
    } catch {}
  }
  return ports;
};
const tail = () => {
  try { return fs.readFileSync(log, "utf8").split("\n").slice(-40).join("\n"); } catch { return ""; }
};
const fail = (msg) => {
  console.log(`serve check failed: ${msg}\n--- server log tail ---\n${tail()}`);
  process.exit(1);
};
const alive = () => { try { process.kill(Number(pid), 0); return true; } catch { return false; } };
const get = (port) => new Promise((resolve) => {
  const req = http.get({ host: "localhost", port, path: "/", timeout: 60000 }, (r) => {
    let body = "";
    r.setEncoding("utf8");
    r.on("data", (d) => { if (body.length < 500000) body += d; });
    r.on("end", () => resolve({ status: r.statusCode, body }));
  });
  req.on("error", (e) => resolve({ error: e.message }));
  req.on("timeout", () => req.destroy(new Error("request timed out")));
});

(async () => {
  const before = listening();
  const end = Date.now() + Number(waitS) * 1000;
  let last = "no new port opened";
  while (Date.now() < end) {
    for (const port of [...listening()].filter((p) => !before.has(p))) {
      const r = await get(port);
      if (r.error) { last = `GET / on port ${port}: ${r.error}`; continue; }
      if (r.status < 200 || r.status >= 400) fail(`GET / returned HTTP ${r.status}`);
      if (!r.body.trim()) fail(`GET / returned an empty body (HTTP ${r.status})`);
      const bad = BAD.find((m) => r.body.includes(m));
      if (bad) fail(`GET / body contains the error marker "${bad}"`);
      console.log(`serve ok: GET / -> HTTP ${r.status}, ${r.body.length} bytes on port ${port}`);
      process.exit(0);
    }
    if (!alive()) fail("server exited before serving");
    await new Promise((r) => setTimeout(r, 1000));
  }
  fail(`${last} within ${waitS}s`);
})();
import json

from resurgo.project import detect_type, dummy_env, needs_secret
from resurgo.run import detect_pm


def test_detect_pm():
    assert detect_pm(["package.json", "pnpm-lock.yaml"]) == "pnpm"
    assert detect_pm(["yarn.lock"]) == "yarn"
    assert detect_pm(["package-lock.json"]) == "npm"
    assert detect_pm(["package.json"]) is None


def pkg(**kw):
    return {"package.json": json.dumps(kw)}


def test_detect_type():
    assert detect_type({"foundry.toml": "", **pkg(name="x")})[0] == "foundry"
    assert detect_type({"Cargo.toml": "[workspace]\n"})[0] == "rust"
    assert detect_type(pkg(devDependencies={"electron": "1"}))[0] == "desktop"
    member = {"apps/a/package.json": '{"dependencies": {"electron": "1"}}'}
    assert detect_type(pkg(name="m"), member)[0] == "desktop"
    assert detect_type({**pkg(name="m"), "pnpm-workspace.yaml": ""})[0] == "monorepo"
    assert detect_type(pkg(workspaces=["a"]))[0] == "monorepo"
    assert detect_type(pkg(scripts={"dev": "vite"}))[0] == "web_app"
    assert detect_type(pkg(dependencies={"express": "4"}))[0] == "web_app"
    assert detect_type(pkg(name="lib", scripts={"build": "tsc"}))[0] == "node_lib"
    assert detect_type({})[0] == "unsupported"
    env = dummy_env("API_KEY=\nSITE_URL=your-url\nPORT=8080 # port\n")
    assert env == "API_KEY=dummy-secret-value\nSITE_URL=http://localhost:3000\nPORT=8080\n"
    assert needs_secret("Error: API_KEY is not set", "API_KEY=\nPORT=1\n") == "API_KEY"


if __name__ == "__main__":
    test_detect_pm()
    test_detect_type()
    print("ok")
